emand/work.py":"[HASH]"},"tested_targets":[],"validated":false},{"artifact_id":"artifact-f9b8a5476f699b7f","branch_id":"v2-8a077b811137-1","content":"{"components/line_windows/work.py": "def compute(payload):\n    \"\"\"按工单 ID 输出合格产线及可行起止窗口三元组，按产线及起点的原遍历顺序。\"\"\"\n    orders = payload.get(\"orders\", [])\n    released = set(payload.get(\"released\", []))\n    routing = payload.get(\"routing\", {})\n    lines = payload.get(\"lines\", [])\n    wip = payload.get(\"wip\", [])\n    freeze = payload.get(\"freeze\", 0)\n    changeover = payload.get(\"changeover\", 0)\n\n    # 每条产线上所有 wip 的结束时间，用于计算最早可排产起点。\n    wip_end = {}\n    for w in wip:\n        line = w.get(\"line\")\n        end = w.get(\"end\", 0)\n        if line not in wip_end or end > wip_end[line]:\n            wip_end[line] = end\n\n    result = {}\n    for order in orders:\n        oid = order[\"id\"]\n        sku = order[\"sku\"]\n        qty = order[\"qty\"]\n        due = order[\"due\"]\n        r = routing.get(sku)\n        if r is None:\n            result[oid] = []\n            continue\n        duration = r.get(\"setup\", 0) + r.get(\"per_unit\", 0) * qty\n        triples = []\n        for line in lines:\n            lid = line[\"id\"]\n            if sku not in line.get(\"qualified\", []) or sku not in released:\n                continue\n            earliest = freeze\n            if lid in wip_end:\n                earliest = max(earliest, wip_end[lid] + changeover)\n            for ws, we in line.get(\"windows\", []):\n                start = max(earliest, ws)\n                while start + duration <= we and start + duration <= due:\n                    triples.append([lid, start, start + duration])\n                    start += 1\n        result[oid] = triples\n    return result\n"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"components/line_windows/work.py":"[HASH]"},"tested_targets":[],"validated":false}],"execution_mode":"parallel_v2","failure_policy":"continue",